import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { Document, Schema as MongooseSchema } from 'mongoose';

// Singleton-style collection, same pattern as EmailSettings: exactly one
// document holds the business's own details, used to brand invoices, email
// templates, and any other customer-facing document generated by the app.
@Schema({ timestamps: true })
export class BusinessInfo extends Document {
  @Prop()
  name?: string;

  @Prop()
  address?: string;

  @Prop()
  town?: string;

  @Prop()
  postcode?: string;

  @Prop()
  telephone?: string;

  @Prop()
  email?: string;

  @Prop()
  website?: string;

  // Base64 data URI, same storage approach as Customer.agreement.signatureImage --
  // no filesystem/blob storage needed, and it survives fine on Render's ephemeral
  // filesystem since it lives in Mongo like everything else.
  @Prop()
  logoImage?: string;

  // termsHtml is what's actually rendered (Business Info preview, the public
  // intake form, the customer PDF export); termsDocx is the original upload,
  // kept only so staff can download back the exact file they gave us -- it's
  // never re-parsed. termsFileName is display-only.
  @Prop()
  termsHtml?: string;

  // Base64 data URI, same storage approach as logoImage above.
  @Prop()
  termsDocx?: string;

  @Prop()
  termsFileName?: string;

  // Free-text version label (e.g. "v2.1") and document date for the currently
  // uploaded terms -- staff-entered, not derived from the file. Stamped onto
  // Customer.agreement at signing time so each customer's record shows which
  // terms revision they actually agreed to.
  @Prop()
  termsVersion?: string;

  @Prop()
  termsDocumentDate?: string;

  // Shown on the public intake form's "Alternative vet care authorisation" step,
  // above the typed-name/signature fields -- staff-editable so the wording can
  // be changed without a code deploy. Falls back to a sensible default in
  // getBusinessInfo() below rather than being required, so this never blocks
  // the intake form if it's never been touched.
  @Prop()
  emergencyVetAuthorisationText?: string;

  // Shown on the public intake form's Off-lead consent section (dogs only),
  // above the typed-name/signature fields -- same staff-editable pattern as
  // emergencyVetAuthorisationText above. `{{petName}}` is substituted with
  // the actual pet's name wherever this is rendered (intake form, customer
  // PDF export), since this one sentence is reused per-dog rather than fixed
  // like the vet authorisation text.
  @Prop()
  offLeadConsentText?: string;

  // Shown on the public intake form's Client agreement step, below the terms
  // and conditions but above the typed-name/signature fields -- same
  // staff-editable pattern as the two above. This text is part of what the
  // signature covers, so it's also included in the customer PDF export.
  @Prop()
  declarationText?: string;

  // The percentage of an invoice's total used by InvoicesService.requestDeposit()
  // to calculate the deposit amount when staff use the "Request Deposit" invoice
  // action. Falls back to a sensible default in getBusinessInfo() below.
  @Prop()
  depositPercentage?: number;

  // Shown to customers on invoices so they know where to send payment --
  // not secret (it's meant to be disclosed), so no encryption, same as the
  // rest of the business's contact details above.
  @Prop()
  bankName?: string;

  @Prop()
  sortCode?: string;

  @Prop()
  accountNumber?: string;

  // Shown in the "Notes" section of the on-screen invoice/quote preview
  // (InvoiceHtmlView.tsx/QuoteHtmlView.tsx) -- separate per document type
  // since staff often want different wording (e.g. payment terms on an
  // invoice vs a call-to-action on a quote). Falls back to a sensible
  // default in getBusinessInfo() below.
  @Prop()
  invoiceNotesMessage?: string;

  @Prop()
  quoteNotesMessage?: string;

  // Numbering for generated invoices/quotes -- {year} and {seq} are
  // substituted by formatDocumentNumber (backend/src/common/document-number.util.ts);
  // *NextNumber is the number the *next* created document will use, and is
  // incremented atomically each time InvoicesService/QuotesService issues one.
  // Both are staff-editable so numbering can be renamed or fast-forwarded
  // (e.g. after deleting documents, or to match an existing paper sequence).
  @Prop({ default: 'INV-{year}-{seq}' })
  invoiceNumberTemplate?: string;

  @Prop({ default: 1 })
  invoiceNextNumber?: number;

  @Prop({ default: 'QUO-{year}-{seq}' })
  quoteNumberTemplate?: string;

  @Prop({ default: 1 })
  quoteNextNumber?: number;

  @Prop({ default: 'PAY-{year}-{seq}' })
  paymentNumberTemplate?: string;

  @Prop({ default: 1 })
  paymentNextNumber?: number;

  @Prop({ default: 'CN-{year}-{seq}' })
  creditNoteNumberTemplate?: string;

  @Prop({ default: 1 })
  creditNoteNextNumber?: number;

  // Freeform layout for the invoice/quote PDF ("View" action, admin/src/pdf/invoicePdf.ts) --
  // an array of staff-positioned blocks (text/image/line/rect/qrcode/itemTable), edited via
  // the drag-and-drop designer at Settings > Invoices. Stored as opaque JSON (Mixed) since it's
  // staff-only structured data the backend never needs to interpret, only round-trip; the
  // frontend owns the actual PdfTemplateElement shape (admin/src/types.ts). Empty/unset means
  // the renderer falls back to its own built-in default layout.
  @Prop({ type: [MongooseSchema.Types.Mixed], default: [] })
  invoicePdfTemplate?: Record<string, unknown>[];

  // Admin-portal login allowlist (Settings > Business Info > Trusted IPs) --
  // empty means unrestricted (the default, so this never blocks anyone until
  // staff deliberately opt in). Only enforced for the admin web app's own
  // login request (see AuthService.login), never for the mobile app, which is
  // used out in the field from arbitrary IPs.
  @Prop({ type: [String], default: [] })
  trustedIps?: string[];

  // The URL a QR code (shown when staff click their avatar in the topbar,
  // Layout.tsx) points at -- typically the admin login page itself, so a
  // staff member can scan it on their phone rather than typing the URL.
  // Staff-editable (Settings > Business Info) rather than derived from an
  // env var, since it's just a convenience shortcut, not something the app
  // depends on functionally.
  @Prop()
  qrLoginUrl?: string;
}

export const BusinessInfoSchema = SchemaFactory.createForClass(BusinessInfo);
